#include <stdio.h>

int main(void) {
    int v, contas[3];
    scanf("%d%d%d%d", &v, &contas[0], &contas[1], &contas[2]);

    for (int i = 0; i < 3; i++) {
        for (int j = i + 1; j < 3; j++) {
            if (contas[i] > contas[j]) {
                int temp = contas[i];
                contas[i] = contas[j];
                contas[j] = temp;
            }
        }
    }

    int total = 0, quantidade = 0;
    for (int i = 0; i < 3; i++) {
        if (total + contas[i] <= v) {
            total += contas[i];
            quantidade++;
        } else {
            break;
        }
    }

    printf("%d\n", quantidade);
    return 0;
}
